SET standard_conforming_strings = ON;
BEGIN;

-- Avoid refreshing large materialized views once per imported row.
-- These trigger changes are transactional and roll back automatically on failure.
DO $disable_summary_triggers$
DECLARE
    trigger_name text;
BEGIN
    FOREACH trigger_name IN ARRAY ARRAY[
        'tgr_set_builtupperwardsummary',
        'tgr_set_landusesummary'
    ]
    LOOP
        IF EXISTS (
            SELECT 1
            FROM pg_trigger t
            JOIN pg_class c ON c.oid = t.tgrelid
            JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE n.nspname = 'fsm'
              AND c.relname = 'containments'
              AND t.tgname = trigger_name
              AND NOT t.tgisinternal
        ) THEN
            EXECUTE format(
                'ALTER TABLE fsm.containments DISABLE TRIGGER %I',
                trigger_name
            );
        END IF;
    END LOOP;
END
$disable_summary_triggers$;
-- Restore normal application trigger behavior before committing.
DO $enable_summary_triggers$
DECLARE
    trigger_name text;
BEGIN
    FOREACH trigger_name IN ARRAY ARRAY[
        'tgr_set_builtupperwardsummary',
        'tgr_set_landusesummary'
    ]
    LOOP
        IF EXISTS (
            SELECT 1
            FROM pg_trigger t
            JOIN pg_class c ON c.oid = t.tgrelid
            JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE n.nspname = 'fsm'
              AND c.relname = 'containments'
              AND t.tgname = trigger_name
              AND NOT t.tgisinternal
        ) THEN
            EXECUTE format(
                'ALTER TABLE fsm.containments ENABLE TRIGGER %I',
                trigger_name
            );
        END IF;
    END LOOP;
END
$enable_summary_triggers$;

COMMIT;

-- Rebuild each summary once after the bulk import.
DO $refresh_available_summaries$
DECLARE
    view_name text;
BEGIN
    FOREACH view_name IN ARRAY ARRAY[
        'builtupperward_summaryforchart',
        'landuse_summaryforchart'
    ]
    LOOP
        IF EXISTS (
            SELECT 1
            FROM pg_matviews
            WHERE schemaname = 'public'
              AND matviewname = view_name
        ) THEN
            EXECUTE format(
                'REFRESH MATERIALIZED VIEW public.%I',
                view_name
            );
        END IF;
    END LOOP;
END
$refresh_available_summaries$;
